// Auto-generated scoped styles for the Interior Studio Page template (terrene port).
// Every rule is scoped under .interior-studio-page so the injected <style> never leaks globals.
export function getInteriorStudioPageStyles(assetBase: string) {
  return (
    INTERIOR_STUDIO_PAGE_STYLES.replaceAll("__ASSET_BASE__", assetBase) +
    STRUCTURAL_STYLES
  );
}

// Structural rules for the ported transition shell plus the body-level rules the
// source kept on <body> (font, background, menu-open pointer lock).
const STRUCTURAL_STYLES = `
.interior-studio-page{width:100%;min-height:100svh;background-color:#0d0c0c;font-family:"Manrope",sans-serif;color:var(--base-100);overflow-x:clip;}
.interior-studio-page .isp-viewport{position:relative;width:100%;min-height:100svh;}
.interior-studio-page .route-layer{position:relative;width:100%;}
.interior-studio-page .route-layer-overlay{position:absolute;top:0;left:0;width:100%;z-index:9000;will-change:transform,clip-path,opacity;}
.interior-studio-page .route-wrapper{position:relative;width:100%;background-color:#0d0c0c;}
.interior-studio-page.menu-open *{pointer-events:none;}
.interior-studio-page.menu-open .menu,
.interior-studio-page.menu-open .menu *,
.interior-studio-page.menu-open .menu-toggle{pointer-events:auto;}
`;

